cat > main.ts <<'EOF'
// Keyed totals: operates on raw bytes so keys compare by bytes and are echoed unchanged.
const MIN = -(1n << 63n);
const MAX = (1n << 63n) - 1n;

const data = Deno.readFileSync(Deno.args[0]);

// Split into lines on \n (byte-wise); keep each as a latin1 string (1 char per byte).
const latin1 = new TextDecoder("latin1");
const lines: Uint8Array[] = [];
let start = 0;
for (let i = 0; i < data.length; i++) {
  if (data[i] === 0x0a) {
    lines.push(data.subarray(start, i));
    start = i + 1;
  }
}
if (start < data.length) lines.push(data.subarray(start));

// If every line ends in \r, treat the file as CRLF.
const crlf = lines.length > 0 && lines.every((l) => l.length > 0 && l[l.length - 1] === 0x0d);
const clean = crlf ? lines.map((l) => l.subarray(0, l.length - 1)) : lines;

const OVERFLOW = Symbol("overflow");
const totals = new Map<string, bigint | typeof OVERFLOW>();

let i = 0;
for (; i < clean.length && clean[i].length > 0; i++) {
  const line = latin1.decode(clean[i]);
  const sp = line.indexOf(" ");
  if (sp < 0) continue;
  const key = line.slice(0, sp);
  const text = line.slice(sp + 1).trim();
  if (!/^[+-]?\d+$/.test(text)) continue;
  const v = BigInt(text);
  const cur = totals.get(key);
  if (cur === OVERFLOW) continue;
  const next = (cur ?? 0n) + v;
  totals.set(key, next < MIN || next > MAX ? OVERFLOW : next);
}
i++; // skip the separator

const enc = new TextEncoder();
const out: Uint8Array[] = [];
const eq = enc.encode("=");
const nl = enc.encode("\n");
for (; i < clean.length; i++) {
  const keyBytes = clean[i];
  const t = totals.get(latin1.decode(keyBytes));
  out.push(keyBytes, eq, enc.encode(t === undefined ? "absent" : t === OVERFLOW ? "overflow" : t.toString()), nl);
}
const buf = new Uint8Array(out.reduce((n, b) => n + b.length, 0));
let off = 0;
for (const b of out) {
  buf.set(b, off);
  off += b.length;
}
let w = 0;
while (w < buf.length) w += Deno.stdout.writeSync(buf.subarray(w));
EOF
